--读写数据
cz.io = function(Path, Data)
    local File, Error
    if Data then
        File, Error = io.open(Path, 'w')
        if not File then
            return false, Error
        end
        File:write(Data)
        File:close()
       -- print('输出一个文件到:\n' .. Path)
    else
        File, Error = io.open(Path, 'r')
        if not File then
            return false, Error
        end
        Data = File:read('*a')
        File:close()
       -- print('输出一个文件到:\n' .. Path)
        return Data
    end
end




