cz.string.encrypt = function(data)
    local Func = load('return ' .. data)
    if not Func then
        data = data:sub(2, -2)
        data = string.format('%q', data)
        Func = load('return ' .. data)
        data = Func()
        data = data:sub(2, -2)
    else
        data = Func()
    end
    if data == '' then
        return '\\034\\034'
    end
    local index = cz.string.used[data]
    if not index then
        local Table, Ascll = {}
        for i, byte in pairs({string.byte(data, 1, -1)}) do
            Ascll = cz.ascll.used[byte]
            if not Ascll then
                Ascll = cz.random.get()
                cz.ascll.used[byte] = Ascll
                table.insert(cz.ascll.data, cz.ascll.name .. "['" .. Ascll .. "']='" .. byte .. "'")
            end
            
            Ascll = '"'..Ascll..'"'
            
            --字符分割1
            if cz.xz[2]==true then
            Ascll=Ascll:gsub('"(.-)"',jia6)
            end
            
            Table[#Table + 1] = Ascll
        end
        Table = '{' .. table.concat(Table, ',') .. '}'
        
        index = '"' .. cz.random.get() .. '"'
        
        --字符分割2
        if cz.xz[2]==true then
        index=index:gsub('"(.-)"',jia6)
        end
        
        
        cz.string.used[data] = index
        table.insert(cz.string.data, cz.string.name .. '[' .. index .. ']=' .. cz.decrypt.name .. '(' .. Table .. ')')
    end
    return ' (' .. cz.string.name .. '[' ..index .. ']) '
end

